def recursively_convert_all_attribute_values(obj):
    if isinstance(obj, int):
        return float(obj)
    if isinstance(obj, float):
        return obj
    if isinstance(obj, str):
        return obj
    if isinstance(obj, list):
        return [recursively_convert_all_attribute_values(item) for item in obj]
    if isinstance(obj, dict):
        return {
            key: recursively_convert_all_attribute_values(value)
            for key, value in obj.items()
