def default_handler(event):
    return {"error": "Event not found", "data": None}

def attach_event_handler(handler, event_name):
    """
    Attaches an event handler to the given HTTP request handler for the specified event name.

    Args:
        handler: An HTTP request handler object that has an 'event_handlers' list.
        event_name (str): The name of the event to attach the handler to.

    Returns:
        None
    """
    # Normalize event name: convert to lowercase and replace special characters with underscores
    normalized_event_name = event_name.lower().replace('-', '_').replace(' ', '_')

    # Define the event handler function
    def event_handler(event_obj):
        # Parse the event object to extract data
        # Assuming event_obj is a dictionary with 'name' and 'data' keys
        if isinstance(event_obj, dict):
            event_data = event_obj.get('data')
            event_name_from_obj = event_obj.get('name', normalized_event_name)
        else:
            event_data = None
            event_name_from_obj = normalized_event_name

        # Check if the event name matches (case-insensitive)
        if event_name_from_obj.lower() == normalized_event_name:
            return {"event": event_name_from_obj, "data": event_data}
        else:
            return default_handler(event_obj)

    # Add the event handler to the handler's event list
    if not hasattr(handler, 'event_handlers'):
        handler.event_handlers = []

    handler.event_handlers.append(event_handler)
