def aggregate_content(dicts):
    result = {}

    for item in dicts:
        target = item.get("target")
        key = item.get("key")
        content = item.get("content", "")

        if target is None or key is None:
            continue

        if target not in result:
            result[target] = {}

        if key not in result[target]:
            result[target][key] = []

        if content:
            result[target][key].append(content)
        else:
            result[target][key].append("None")

    # Concatenate lists with newline separator
    final_result = {}
    for target, keys_dict in result.items():
        final_result[target] = {}
        for key, content_list in keys_dict.items():
            final_result[target][key] = "\n".join(content_list)

    return final_result
