def bin2dec(binary_str: str) -> int:
    """Convert a binary string to its decimal equivalent using bitwise operations."""
    result = 0
    for ch in binary_str:
        if ch not in ('0', '1'):
            raise ValueError(f"Invalid binary digit: {ch}")
        result = (result << 1) | int(ch)
    return result

def dec2bin(n: int) -> str:
    """Convert a non-negative integer to its binary string representation."""
    if n == 0:
        return '0'
    bits = []
    while n > 0:
        bits.append(str(n & 1))
        n >>= 1
    return ''.join(reversed(bits))
