import math

def calculate_mean_and_std(matrix):
    if not matrix or not all(matrix):
        return {'mean': 0.0, 'std': 0.0}

    total = 0.0
    count = 0
    for row in matrix:
        for val in row:
            total += val
            count += 1

    mean = total / count if count > 0 else 0.0

    sum_sq_diff = 0.0
    for row in matrix:
        for val in row:
            sum_sq_diff += (val - mean) ** 2

    variance = sum_sq_diff / count if count > 0 else 0.0
    std = math.sqrt(variance)

    return {'mean': mean, 'std': std}
