def convertint(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    s = str(abs(n))
    if s == "0":
        return "0"

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            if count > 3:
                # Replace the run of identical digits with the digit itself
                result.append(s[i - 1])
            else:
                result.append(s[i - 1] * count)
            count = 1

    # Handle the last run
    if count > 3:
        result.append(s[-1])
    else:
        result.append(s[-1] * count)

    return str(n) if n >= 0 else "-" + "".join(result)
