def copy_number_variation(json_object):
    """
    Calculate the relative copy number variation of a gene based on a given JSON object
    containing the total copy numbers of the gene in different tissues.

    The function assumes the input JSON object has a structure like:
    {
        "reference_copy_number": 2,
        "tissues": {
            "tissue1": 2,
            "tissue2": 3,
            ...
        }
    }

    It returns a dictionary with the variation percentage for each tissue relative to the reference.
    Variation percentage = ((tissue_copy_number - reference_copy_number) / reference_copy_number) * 100

    Parameters:
    json_object (dict): A dictionary containing 'reference_copy_number' and 'tissues' keys.

    Returns:
    dict: A dictionary with tissue names as keys and their variation percentages as values.
    """
    if not isinstance(json_object, dict):
        raise ValueError("Input must be a dictionary.")

    if "reference_copy_number" not in json_object:
        raise ValueError("Missing 'reference_copy_number' in the input JSON object.")

    if "tissues" not in json_object:
        raise ValueError("Missing 'tissues' in the input JSON object.")

    reference = json_object["reference_copy_number"]
