def validate_number(argument, allow_numbers=['int', 'float', 'str']):
    # Normalize allow_numbers to actual types if strings are provided
    allowed_types = []
    for t in allow_numbers:
        if t == 'int':
            allowed_types.append(int)
        elif t == 'float':
            allowed_types.append(float)
        elif t == 'str':
            allowed_types.append(str)
        else:
            # If an unknown type string is passed, skip it
            continue

    # If no types are allowed, return False
    if not allowed_types:
        return False

    # Check if argument is one of the allowed types
    if isinstance(argument, allowed_types):
        # Special handling for float: check for NaN and Inf
        if isinstance(argument, float):
            if math.isnan(argument) or math.isinf(argument):
                return False
            return True
        # For int and str, they are considered valid numbers
        return True

    # If argument is a string, try to convert to float and validate
    if isinstance(argument, str):
        # Strip whitespace
        s = argument.strip()
        if not s:
            return False

        # Check for valid numeric string patterns (including scientific notation)
        # But exclude 'nan', 'inf', 'NaN', 'Inf', etc.
        lower_s = s.lower()
        if lower_s in ('nan', 'inf', '+inf', '-inf', '+nan', '-nan'):
            return False

        # Try to convert to float
        try:
            val = float(s)
            if math.isnan(val) or math.isinf(val):
                return False
            return True
        except ValueError:
            return False

    # If argument is not a string and not in allowed types, return False
    return False
