# Global variable to store the index range list
index_list = []

def reset_dataframe(df: pd.DataFrame) -> pd.DataFrame:
    # Check the type of the index
    if isinstance(df.index, pd.RangeIndex):
        # For RangeIndex, simply reset the index
        return df.reset_index(drop=True)
    elif isinstance(df.index, pd.Int64Index):
        # For Int64Index, create a list of integers from min to max
        global index_list
        min_val = df.index.min()
        max_val = df.index.max()
        index_list = list(range(min_val, max_val + 1))

        # Set the index to the generated list and then reset it
        df.index = index_list
        return df.reset_index(drop=True)
    else:
        # For other index types, just reset the index
        return df.reset_index(drop=True)
