def add_spaces_to_tabs(filename, num_spaces=4):
    """
    Reads a text file and adds a fixed number of spaces to the end of each line.

    Args:
        filename (str): Path to the input text file.
        num_spaces (int): Number of spaces to add to the end of each line.

    Returns:
        None: The modified content is written back to the same file.
    """
    try:
        with open(filename, 'r', encoding='utf-8') as file:
            lines = file.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {filename} does not exist.")
    except Exception as e:
        raise Exception(f"An error occurred while reading the file: {e}")

    try:
        with open(filename, 'w', encoding='utf-8') as file:
            for line in lines:
                # Ensure we don't add extra spaces if the line is empty or just a newline
                if line.endswith('\n'):
                    file.write(line + ' ' * num_spaces + '\n')
                else:
                    file.write(line + ' ' * num_spaces)
    except Exception as e:
        raise Exception(f"An error occurred while writing to the file: {e}")
