def create_uri(uri_string):
    # Default protocol
    protocol = 'http'

    # Check if the string starts with 'https://'
    if uri_string.startswith('https://'):
        protocol = 'https'
        uri_string = uri_string[8:]  # Remove 'https://'
    elif uri_string.startswith('http://'):
        protocol = 'http'
        uri_string = uri_string[7:]  # Remove 'http://'

    # Now uri_string should be 'netloc/path?query#fragment' or parts thereof
    # Split by '?' to separate path+fragment from query
    if '?' in uri_string:
        path_and_fragment, query = uri_string.split('?', 1)
        # Check for fragment in path_and_fragment
        if '#' in path_and_fragment:
            path, fragment = path_and_fragment.split('#', 1)
            if query:
                return f"{protocol}://{path_and_fragment}?{query}"
            else:
                return f"{protocol}://{path_and_fragment}#{fragment}"
        else:
            path = path_and_fragment
            if query:
                return f"{protocol}://{path}?{query}"
            else:
                return f"{protocol}://{path}"
    else:
        # No query or fragment
        if '#' in uri_string:
            path, fragment = uri_string.split('#', 1)
            return f"{protocol}://{path}#{fragment}"
        else:
            path = uri_string
            return f"{protocol}://{path}"
