def parse_column_names(column_names_str):
    if not column_names_str or not column_names_str.strip():
        return []

    # Remove leading and trailing commas from the whole string
    column_names_str = column_names_str.strip()
    while column_names_str.startswith(','):
        column_names_str = column_names_str[1:]
    while column_names_str.endswith(','):
        column_names_str = column_names_str[:-1]

    if not column_names_str:
        return []

    # Split by comma
    parts = column_names_str.split(',')

    result = []
    for part in parts:
        # Remove leading and trailing spaces
        part = part.strip()
        # Remove leading and trailing commas (in case they slipped through)
        while part.startswith(','):
            part = part[1:]
        while part.endswith(','):
            part = part[:-1]
        # Remove spaces again after removing commas
        part = part.strip()
        if part:
            result.append(part)

    return result
