from typing import List

def generate_slack_block(input_data: List[List[str]], row_labels: List[str], col_labels: List[str]) -> List[dict]:
    """
    Generates a list of Slack message blocks representing a table.

    Args:
        input_data: List of lists containing the data for each row.
        row_labels: List of labels for each row.
        col_labels: List of labels for each column.

    Returns:
        A list of dictionaries representing Slack message blocks.
    """
    blocks = []

    # Header section
    header_text = " | ".join(col_labels)
    header_divider = " | ".join(["---" for _ in col_labels])

    blocks.append({
        "type": "header",
        "text": {
            "type": "plain_text",
            "text": header_text
        }
    })

    blocks.append({
        "type": "divider"
    })

    blocks.append({
        "type": "header",
        "text": {
            "type": "plain_text",
            "text": header_divider
        }
    })

    # Data rows
    for i, row_data in enumerate(input_data):
        row_text = " | ".join([row_data[j] if j < len(row_data) else "" for j in range(len(col_labels))])

        blocks.append({
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": f"*{row_labels[i]}* | {row_text}"
            }
        })

    return blocks
