def pixels_match(image1, image2):
    """
    Compare two images to determine if they are identical pixel by pixel.

    Args:
        image1 (list of lists of lists of int): First image represented as a 3D list [height][width][channels].
        image2 (list of lists of lists of int): Second image represented as a 3D list [height][width][channels].

    Returns:
        bool: True if the images are identical, False otherwise.
    """
    # Check if dimensions match
    if len(image1) != len(image2):
        return False
    if any(len(row1) != len(row2) for row1, row2 in zip(image1, image2)):
        return False
    if any(len(pixel1) != len(pixel2) for row1, row2 in zip(image1, image2) for pixel1, pixel2 in zip(row1, row2)):
        return False

    # Compare each pixel value
    for row1, row2 in zip(image1, image2):
        for pixel1, pixel2 in zip(row1, row2):
            for val1, val2 in zip(pixel1, pixel2):
                if val1 != val2:
                    return False
    return True
