def shortest_path(grid, start, target):
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    start_r, start_c = start
    target_r, target_c = target

    # Validate start and target positions
    if not (0 <= start_r < rows and 0 <= start_c < cols):
        return []
    if not (0 <= target_r < rows and 0 <= target_c < cols):
        return []

    # Check if start or target is an obstacle
    if grid[start_r][start_c] == 1 or grid[target_r][target_c] == 1:
        return []

    if start == target:
        return [start]

    from collections import deque

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        (r, c), path = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    new_path = path + [(nr, nc)]
                    if (nr, nc) == target:
                        return new_path
                    visited.add((nr, nc))
                    queue.append(((nr, nc), new_path))

    return []
```

