def contains_pair(obj, key, value):
    """
    Recursively checks whether a given JSON object contains a specific key-value pair.
    Traverses all nested objects and arrays.

    Args:
        obj: The JSON object (dict, list, or primitive) to search.
        key: The key to look for.
        value: The value to match for the key.

    Returns:
        True if the key-value pair is found at any level, False otherwise.
