def binomial_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    # Use dynamic programming with a 1D array to compute C(n, k)
    # C(i, j) = C(i-1, j-1) + C(i-1, j)
    # We only need the previous row to compute the current row.
    row = [0] * (k + 1)
    row[0] = 1  # C(i, 0) = 1 for all i

    for i in range(1, n + 1):
        # Update row in reverse to avoid overwriting values needed for the same iteration
        for j in range(min(i, k), 0, -1):
            row[j] = row[j] + row[j - 1]

    return row[k]
