import os
import random

def select_files_for_subsample(subdirectories, target_size):
    # Preconditions
    if not isinstance(target_size, int) or target_size <= 0:
        raise ValueError("target_size must be a positive integer.")
    if not isinstance(subdirectories, list) or len(subdirectories) == 0:
        raise ValueError("subdirectories must be a non-empty list.")

    selected_files = []
    current_total_size = 0

    # Helper to get file size
    def get_file_size(file_path):
        try:
            return os.path.getsize(file_path)
        except (OSError, FileNotFoundError):
            return 0  # Skip invalid files

    # Collect all valid files from subdirectories
    all_files = []
    for subdir in subdirectories:
        if not os.path.isdir(subdir):
            continue
        for root, _, files in os.walk(subdir):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.isfile(file_path):
                    all_files.append(file_path)

    # If no files found, return empty list
    if not all_files:
        return []

    # Check total size of all files
    total_size = sum(get_file_size(f) for f in all_files)

    if total_size <= target_size:
        return all_files

    # Randomly select files until we reach or exceed target_size
    # We'll shuffle and pick greedily
    random.shuffle(all_files)

    for file_path in all_files:
        file_size = get_file_size(file_path)
        if current_total_size + file_size <= target_size:
            selected_files.append(file_path)
            current_total_size += file_size
        else:
            # Even if adding this file exceeds target, we stop because
            # the requirement is "less than or equal to target_size"
            break

    return selected_files
