def parameter_registry(registry=None):
    if registry is None:
        registry = {}

    def decorator(func):
        def wrapper(*args, **kwargs):
            func_name = func.__name__
            all_params = list(args) + [kwargs]

            if func_name in registry:
                registry[func_name].append(all_params)
