def my_atoi(string):
    if not isinstance(string, str):
        return None

    s = string.strip()
    if not s:
        return None

    index = 0
    sign = 1

    if s[0] == '-':
        sign = -1
        index = 1
    elif s[0] == '+':
        index = 1

    if index >= len(s):
        return None

    result = 0
    digits = []

    while index < len(s):
        char = s[index]
        if '0' <= char <= '9':
            digits.append(int(char))
            index += 1
        else:
            break

    if not digits:
        return None

    # Check for overflow before computing final value
    # Python handles large integers automatically, but we mimic 32-bit signed integer limits if needed.
    # Here we just return the integer as Python allows arbitrary precision.
    value = sign * sum(d * (10 ** (len(digits) - 1 - i)) for i, d in enumerate(digits))

    return value
