def normalize_dict_0_to_100(d):
    # Filter out non-numeric values (strings, etc.)
    numeric_values = [v for v in d.values() if isinstance(v, (int, float)) and not isinstance(v, bool)]

    if not numeric_values:
        # If no numeric values, return an empty dictionary or original with no changes
        return {}

    min_val = min(numeric_values)
    max_val = max(numeric_values)

    # Handle case where all numeric values are the same
    if max_val == min_val:
        return {k: 100.0 for k in d if isinstance(d[k], (int, float)) and not isinstance(d[k], bool)}

    normalized = {}
    for k, v in d.items():
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            # Normalize to 0-100 range
            normalized[k] = round((v - min_val) / (max_val - min_val) * 100, 6)
        else:
            # Keep non-numeric values as-is (though spec says ignore strings, we keep them unchanged)
            normalized[k] = v

    return normalized
