def string_to_cents(string: str) -> int:
    if not isinstance(string, str):
        raise ValueError("Input must be a string.")

    if not string.startswith("$"):
        raise ValueError("String must start with '$'.")

    # Remove the leading '$' and any surrounding whitespace
    value_str = string[1:].strip()

    if not value_str:
        raise ValueError("Empty currency string after '$'.")

    # Split into integer and decimal parts
    if '.' in value_str:
        parts = value_str.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid currency format: multiple decimal points.")
        integer_part, decimal_part = parts
        if not integer_part.isdigit() or not decimal_part.isdigit():
            raise ValueError("Invalid currency format: non-digit characters found.")
        if len(decimal_part) > 2:
            raise ValueError("Invalid currency format: more than two decimal places.")
        # Pad or truncate decimal part to exactly 2 digits
        decimal_part = decimal_part.ljust(2, '0')[:2]
        cents = int(integer_part) * 100 + int(decimal_part)
    else:
        if not value_str.isdigit():
            raise ValueError("Invalid currency format: non-digit characters found.")
        cents = int(value_str) * 100

    if cents < 0:
        raise ValueError("Currency value cannot be negative.")

    return cents
