        if value is None or value == "":
            return None
        if isinstance(value, (int, float)):
            return value
        if isinstance(value, str):
            # Try to convert string to int first
            try:
                return int(value)
            except ValueError:
                pass
            # Then try to convert to float
            try:
                return float(value)
            except ValueError:
                pass
        # If it's not a string and not a number, and not None/empty, keep as is
        # But per spec, we only ensure numeric values are int/float; others pass through
        return value

