            continue

        processed_entry = {}
        valid_entry = True

        for key, value in entry.items():
            converted = convert_value(value)
            if converted is None:
                valid_entry = False
                break
            processed_entry[key] = converted

        if valid_entry:
            result.append(processed_entry)

    return result if result else []
