def recursive_operation(operator, integer):
    def add_one(n):
        return n + 1

    def sub_one(n):
        return n - 1

    def mul_recursive(a, b):
        if b == 0:
            return 0
        if b < 0:
            return -mul_recursive(a, -b)
        return a + mul_recursive(a, b - 1)

    def div_recursive(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        if a == 0:
            return 0
        if a < 0:
            return -div_recursive(-a, b)
        if b < 0:
            return -div_recursive(a, -b)
        count = 0
        while a >= b:
            a = a - b
            count += 1
        return count

    if operator == 'add':
        return add_one(integer)
    elif operator == 'sub':
        return sub_one(integer)
    elif operator == 'mul':
        return mul_recursive(integer, 2)
    elif operator == 'div':
        return div_recursive(integer, 2)
    else:
        raise ValueError(f"Unsupported operator: {operator}")
