from typing import Any, Dict, List, Union

def aggregator(dicts: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not dicts:
        return {}

    # Collect all keys and verify they are consistent across all dictionaries
    keys = set(dicts[0].keys())
    for d in dicts:
        if set(d.keys()) != keys:
            raise ValueError("All dictionaries must have the same keys.")

    result: Dict[str, Any] = {}

    for key in keys:
        values = [d[key] for d in dicts]

        # Check if all values are the same
        if all(v == values[0] for v in values):
            result[key] = values[0]
        else:
            # Check if all values are numbers (int or float)
            if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
                result[key] = sum(values)
            else:
                # Return the most commonly occurring value
                counter = Counter(values)
                result[key] = counter.most_common(1)[0][0]

    return result
