import types

def copy_function(func):
    """
    Return a copy of a function with the same code, name, and docstring as the original function.
    The copied function maintains the same function attributes (including __doc__) as the original.
    """
    if not isinstance(func, types.FunctionType):
        raise TypeError("copy_function: expected a function, got %s" % type(func).__name__)

    # Create a new function object with the same code object, name, and docstring
    new_func = types.FunctionType(
        func.__code__,
        func.__globals__,
        func.__name__,
        func.__defaults__,
        func.__closure__
    )

    # Copy additional attributes manually to ensure they are preserved
    for attr in ('__doc__', '__kwdefaults__', '__annotations__', '__module__', '__qualname__', '__dict__'):
        if hasattr(func, attr):
            setattr(new_func, attr, getattr(func, attr))

    return new_func
