def two_smallest_keys(d):
    if not d:
        return []

    # Sort items by value, then by key for deterministic order
    sorted_items = sorted(d.items(), key=lambda x: (x[1], x[0]))

    # Collect keys for the two smallest values
    result = []
    min_value = None
    second_min_value = None

    # First pass: determine the two smallest distinct values
    for key, value in sorted_items:
        if min_value is None:
            min_value = value
        elif second_min_value is None:
            second_min_value = value
        else:
            break

    # If all values are the same, return all keys
    if min_value == second_min_value:
        return list(d.keys())

    # Collect all keys with the smallest value
    for key, value in d.items():
        if value == min_value:
            result.append(key)

    # Collect all keys with the second smallest value
    for key, value in d.items():
        if value == second_min_value:
            result.append(key)

    return result
