class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generate_all_paths(root, path):
    if root is None:
        return []

    # Add current node value to the path
    path.append(root.val)

    result = []

    # If it's a leaf node, add the current path to results
    if root.left is None and root.right is None:
        result.append(list(path))
    else:
        # Recurse on left child
        if root.left:
            result.extend(generate_all_paths(root.left, path))

        # Recurse on right child
        if root.right:
            result.extend(generate_all_paths(root.right, path))

    # Backtrack: remove current node value from path before returning
    path.pop()

    return result
