def get_value_from_attributes(element, attribute, path):
    """
    Retrieves a value from nested attributes of an XML element.

    Args:
        element: An XML element object.
        attribute: The name of the attribute to look for.
        path: A string representing the path to the attribute (e.g., "parent.child.attr").

    Returns:
        The value of the attribute if found, otherwise an empty string.
    """
    if not element or not attribute or not path:
        return ""

    try:
        parts = path.split('.')
        current = element

        for part in parts:
            if not part:
                return ""

            # Check if current is an element or a dict-like object
            if hasattr(current, 'get'):
                # Try to get the attribute directly if it's a dict-like object
                if part in current:
                    current = current[part]
                else:
                    return ""
            elif hasattr(current, 'attrib'):
                # Standard xml.etree.ElementTree element
                if part in current.attrib:
                    current = current.attrib[part]
                else:
                    return ""
            elif hasattr(current, '__getitem__'):
                # Fallback for other dict-like objects
                if part in current:
                    current = current[part]
                else:
                    return ""
            else:
                return ""

        # If we reached here, we have the final value
        # If the final part is an attribute name, we need to get it from the last element
        if hasattr(current, 'attrib') and attribute in current.attrib:
            return current.attrib[attribute]
        elif hasattr(current, 'get') and attribute in current:
            return current[attribute]
        else:
            return ""

    except Exception:
        return ""
