def scale_and_normalize_values(values):
    if not values:
        return []

    min_value = min(values)
    max_value = max(values)

    # Avoid division by zero if all values are the same
    if max_value == min_value:
        return [0.0] * len(values)

    # Scale values
    scaled_values = [(v - min_value) / (max_value - min_value) for v in values]

    max_scaled_value = max(scaled_values)

    # Normalize by dividing by the maximum scaled value
    if max_scaled_value == 0:
        return [0.0] * len(values)

    normalized_values = [s / max_scaled_value for s in scaled_values]

    return normalized_values
