class GraphNode:
    def __init__(self, value: int, neighbors: Optional[List['GraphNode']] = None):
        self.value = value
        self.neighbors = neighbors or []

def dfs_traverse(node: GraphNode, probabilities: Dict[int, float], visited: Set[int]) -> List[int]:
    if node.value in visited:
        return []

    visited.add(node.value)
    result = [node.value]

    for neighbor in node.neighbors:
        # Filter edges: only visit if the neighbor's probability of success is non-zero
        if neighbor.value in probabilities and probabilities[neighbor.value] > 0:
            result.extend(dfs_traverse(neighbor, probabilities, visited))

    return result
