def dotted_quad_to_hex(address: str) -> str:
    """
    Convert a dotted-quad IP address string to a hexadecimal string.

    Each octet is converted to its two-digit hexadecimal representation prefixed with '0x',
    and the four parts are joined with '.'.

    Raises:
        ValueError: If the input is not a valid dotted-quad IP address.
    """
    parts = address.split('.')
    if len(parts) != 4:
        raise ValueError("Invalid IP address format: expected 4 octets separated by dots.")

    hex_parts = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid octet: '{part}' is not a valid number.")

        try:
            octet = int(part)
        except ValueError:
            raise ValueError(f"Invalid octet: '{part}' cannot be converted to an integer.")

        if not (0 <= octet <= 255):
            raise ValueError(f"Invalid octet value: '{octet}' must be between 0 and 255.")

        hex_parts.append(f"0x{octet:02x}")

    return ".".join(hex_parts)
