def tensor_from_array(array, framework='pytorch', device='cpu'):
    """
    Converts a 1D array to a tensor compatible with the specified framework (PyTorch or TensorFlow).

    Parameters:
        array (list or 1D array-like): Input data.
        framework (str): 'pytorch' or 'tensorflow'.
        device (str): Device to place the tensor ('cpu' or 'cuda' for PyTorch; 'cpu' or 'gpu' for TensorFlow).

    Returns:
        torch.Tensor or tf.Tensor: The resulting tensor.
    """
    if framework == 'pytorch':
        if device == 'cuda' and not torch.cuda.is_available():
            raise RuntimeError("CUDA is not available but 'cuda' device was requested.")
        tensor = torch.tensor(array, dtype=torch.float32)
        if device == 'cuda':
            tensor = tensor.to('cuda')
        return tensor
    elif framework == 'tensorflow':
        if device == 'gpu' and not tf.config.list_physical_devices('GPU'):
            raise RuntimeError("No GPU found but 'gpu' device was requested.")
        tensor = tf.constant(array, dtype=tf.float32)
        if device == 'gpu':
            try:
                gpus = tf.config.list_physical_devices('GPU')
                if gpus:
                    tf.config.set_visible_devices(gpus[0], 'GPU')
                    tensor = tensor.device('GPU:0')
            except RuntimeError as e:
                raise RuntimeError(f"Could not set device to GPU: {e}")
        return tensor
    else:
        raise ValueError(f"Unsupported framework: {framework}. Choose 'pytorch' or 'tensorflow'.")
