                    self.urls.append(value)

def extract_hyperlinks(html):
    parser = LinkExtractor()
    try:
        parser.feed(html)
    except Exception:
        pass

    # Use regex to find any remaining hrefs in case of malformed tags not fully parsed
    # This acts as a fallback for robustness while still using regex as requested
    regex_pattern = r'<a\s+[^>]*href\s*=\s*["\']([^"\']+)["\']'
    regex_matches = re.findall(regex_pattern, html, re.IGNORECASE | re.DOTALL)

    # Combine results, removing duplicates while preserving order
    seen = set()
    result = []
    for url in parser.urls + regex_matches:
        if url not in seen:
            seen.add(url)
            result.append(url)

