def justify_words(line_length, words):
    if not words:
        return -1

    total_chars = sum(len(w) for w in words)
    num_gaps = len(words) - 1

    if total_chars > line_length:
        return -1

    if num_gaps == 0:
        # Single word: pad with spaces to the left to reach line_length
        return words[0] + ' ' * (line_length - len(words[0]))

    # Calculate minimum required spaces (1 per gap)
    min_spaces = num_gaps
    extra_spaces = line_length - total_chars - min_spaces

    # Distribute extra spaces as evenly as possible, with left gaps getting more if needed
    gaps = []
    for i in range(num_gaps):
        base = extra_spaces // num_gaps
        extra = 1 if i < extra_spaces % num_gaps else 0
        gaps.append(base + extra)

    # Build the justified line
    result_parts = []
    for i, word in enumerate(words):
        result_parts.append(word)
        if i < num_gaps:
            result_parts.append(' ' * gaps[i])

    return ''.join(result_parts)
