def bitwise_left_rotation(x: int, n: int) -> int:
    if x < 0:
        raise ValueError("x must be a non-negative integer")
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Determine the number of bits required to represent x
    if x == 0:
        num_bits = 1
    else:
        num_bits = x.bit_length()

    # Normalize n to be within the range [0, num_bits)
    n = n % num_bits

    # Perform the left rotation
    return ((x << n) | (x >> (num_bits - n))) & ((1 << num_bits) - 1)
```

