def count_bits_set_to_1(n):
    # Handle invalid inputs: non-integers or negative numbers (if we consider only non-negative integers)
    if not isinstance(n, int):
        return -1
    if n < 0:
        return -1

    count = 0
    while n:
        n &= n - 1  # Clear the least significant bit set to 1
        count += 1
    return count
